struct RequireRole: AsyncMiddleware {
    let role: String
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        let user = try request.auth.require(User.self)          // subject
        guard user.roles.contains(role) else { throw Abort(.forbidden) }   // decision
        return try await next.respond(to: request)              // enforcement passes
    }
}

let admin = app.grouped(UserAuthenticator())
    .grouped(User.guardMiddleware())
    .grouped(RequireRole(role: "admin"))
admin.get("orders") { req in try await OrderController().list(req) }
